      dp[i][0] = True
  for i in range(1, len(arr)): 
    for j in range(1, target + 1): 
      if dp[i - 1][j]: 
          dp[i][j] = dp[i - 1][j] 
      elif j >= arr[i]: 
          dp[i][j] = dp[i - 1][j - arr[i]] 
  max_val = 0
  for i in range(1, target + 1): 
